-- Table structure for `fixture_scores`
DROP TABLE IF EXISTS `fixture_scores`;
CREATE TABLE IF NOT EXISTS `fixture_scores` (
  `id` VARCHAR(255) DEFAULT NULL NOT NULL PRIMARY KEY,
  `fixture_ref` VARCHAR(255) DEFAULT NULL,
  `fulltime_home` VARCHAR(255) DEFAULT NULL,
  `fulltime_away` VARCHAR(255) DEFAULT NULL,
  `halftime_home` VARCHAR(255) DEFAULT NULL,
  `halftime_away` VARCHAR(255) DEFAULT NULL,
  `extratime_home` VARCHAR(255) DEFAULT NULL,
  `extratime_away` VARCHAR(255) DEFAULT NULL,
  `penalty_home` VARCHAR(255) DEFAULT NULL,
  `penalty_away` VARCHAR(255) DEFAULT NULL,
  `created_at` VARCHAR(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

